# Skill ids that would collide with the reserved memory namespaces
# (``project.*`` and ``system.*`` — skill entries resolve to
# ``{skill_id}.{entry_name}`` slots).
_RESERVED_SKILL_IDS = frozenset({PROJECT_NAMESPACE, SYSTEM_NAMESPACE})
_MISSING_SKILL_DESCRIPTION_CODE = "mantle.validation.skill.missing_description"
_NO_ENTRY_BLOCK_CODE = "mantle.validation.skill.no_entry_block"
_MULTIPLE_ENTRY_BLOCKS_CODE = "mantle.validation.skill.multiple_entry_blocks"
_UNREACHABLE_ORDERED_BLOCK_CODE = "mantle.validation.skill.unreachable_ordered_block"
_SILENCE_TIMEOUT_HANGUP_BLOCK_CODE = (
    "mantle.validation.skill.silence_timeout_hangup_block"
)
_SILENCE_TIMEOUT_HANGUP_BLOCK_ID = "hangup"
_REFERENCED_TARGET_CODE = "skill.referenced.invalid_target"
_BARE_SKILL_MENTION_CODE = "skill.prose.bare_skill_mention"
_HIDDEN_PROSE_SKILL_REF_CODE = "skill.prose.hidden_skill_reference"
_REFERENCED_BLOCK_CODE = "skill.referenced.invalid_block"
_IMPORT_TOOLS_CODE = "skill.import_tools.invalid_shared_tool"
_UNKNOWN_ON_SUCCESS_OR_FAILURE_CODE = (
    "mantle.validation.tool_constraint.unknown_on_success_or_failure"
)
_UNKNOWN_VERBATIM_TRIGGER_RESPONSE_CODE = (
    "mantle.validation.verbatim_trigger.unknown_response"
)
_EMPTY_RESPONSE_BODY_CODE = "mantle.validation.response.empty_body"
_MISSING_PRECONDITION_BINDING_CODE = "mantle.validation.precondition.missing_binding"
_INVALID_PRECONDITION_SYNTAX_CODE = (
    "mantle.validation.precondition.invalid_satisfied_when"
)
_UNKNOWN_PRECONDITION_RESOLVER_CODE = "mantle.validation.precondition.unknown_resolver"
_NESTED_PRECONDITION_RESOLVER_CODE = "mantle.validation.precondition.nested_resolver"
_SELF_RESOLVE_PRECONDITION_CODE = "mantle.validation.precondition.self_resolve"
_PRECONDITION_CYCLE_CODE = "mantle.validation.precondition.cycle"
_UNKNOWN_REQUIRES_CONFIRMATION_RESPONSE_CODE = (
    "mantle.validation.tool_constraint.unknown_requires_confirmation_response"
)
_EMPTY_IF_CONDITION_CODE = "mantle.validation.prose.empty_if_condition"
_INVALID_IF_EXPRESSION_CODE = "mantle.validation.prose.invalid_if_expression"
_UNKNOWN_MEMORY_KEY_CODE = "mantle.validation.prose.unknown_memory_key"
_UNKNOWN_MEMORY_REFERENCE_CODE = "mantle.validation.prose.unknown_memory_reference"
_INCOMPLETE_MEMORY_REFERENCE_CODE = (
    "mantle.validation.prose.incomplete_memory_reference"
)
_INCOMPLETE_AT_REFERENCE_CODE = "mantle.validation.prose.incomplete_at_reference"
_SESSION_IN_INSTRUCTIONS_CODE = (
    "mantle.validation.prose.session_reference_in_instructions"
)
# Canonical two-level form in free text (same shape as conditions / @memory).
_PROSE_SESSION_REF_PATTERN = re.compile(r"(?<![\w.])session\.([\w-]+)\.([\w-]+)")
_INVALID_EXECUTE_SESSION_PARAM_CODE = (
    "mantle.validation.execute_step.invalid_session_parameter"
)
_UNKNOWN_EXECUTE_SESSION_PARAM_CODE = (
    "mantle.validation.execute_step.unknown_memory_key"
)


def validate_skill_loading(
    project_result: SkillCatalogLoadResult,
) -> list[ValidationFinding]:
    """Report skill directories that fail to load or collide on skill id.

    The catalog loader logs-and-skips unparseable skills, so without this a
    broken skill would silently vanish and let ``validate_project`` pass (and
    the broken ``skills/`` tree still gets packaged). Likewise, two project
    skill directories declaring the same ``id:`` would silently resolve to
    whichever sorts later. Reporting both keeps the validator honest.
    """
    findings = [
        ValidationFinding(
            code="mantle.validation.skill.failed_to_load",
            message=(
                f"Skill directory '{MANTLE_SKILLS_DIR}/{directory}' failed to load "
                f"and would be silently skipped: {error}. Fix the skill so it "
                "parses, or remove it."
            ),
        )
        for directory, error in project_result.load_errors
    ]
    findings.extend(
        ValidationFinding(
            code="mantle.validation.skill.duplicate_id",
            message=(
                f"Skill directories '{MANTLE_SKILLS_DIR}/{duplicate.first_directory}' "
                f"and '{MANTLE_SKILLS_DIR}/{duplicate.second_directory}' both declare "
                f"skill id {duplicate.skill_id!r}; only "
                f"'{MANTLE_SKILLS_DIR}/{duplicate.second_directory}' would be loaded. "
                "Give each skill a unique 'id'."
            ),
        )
        for duplicate in project_result.duplicate_ids
    )
    return findings


def validate_skill_descriptions(catalog: SkillCatalog) -> list[ValidationFinding]:
    """Require a non-empty ``description`` on every skill.

    The orchestrator matches routing against this text. A missing or
    whitespace-only value leaves the catalogue entry unlabeled.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        if _has_nonempty_description(skill.description):
            continue
        findings.append(
            ValidationFinding(
                code=_MISSING_SKILL_DESCRIPTION_CODE,
                message=_missing_skill_description_message(skill),
            )
        )
    return findings


def _has_nonempty_description(description: str | None) -> bool:
    """Return whether *description* is a usable routing summary."""
    return bool(description and description.strip())


def _missing_skill_description_message(skill: Skill) -> str:
    """Return the train-time message for a skill with no description."""
    prefix = (
        f"Skill {skill.id!r} has no description. Add a non-empty "
        "'description' in skill.md frontmatter"
    )
    if skill.hidden:
        return (
            f"{prefix}; hidden skills are not orchestrator routing targets, "
            "but the field is still required."
        )
    return f"{prefix}; the orchestrator routes on that text."


def validate_ordered_block_structure(catalog: SkillCatalog) -> list[ValidationFinding]:
    """Reject blocks-only skills with a bad entry.

    A blocks-only skill has exactly one entry block: the only ordered block
    that is not the target of a same-skill ``call:`` or ``link:``. Every
    other block must be reachable from that entry. Bundled and
    engine-managed skills use the same rule. An override of
    ``default_silence_timeout`` that still contains a ``hangup`` block fails
    even when that block is reachable.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        findings.extend(_ordered_block_structure_findings(skill))
    return findings


def _ordered_block_structure_findings(skill: Skill) -> list[ValidationFinding]:
    """Return entry findings for one skill."""
    findings: list[ValidationFinding] = []
    if skill_has_prose(skill):
        return findings
    blocks = ordered_blocks_in_body(skill)
    if not blocks:
        return findings
    entries = entry_block_ids(skill)
    if len(entries) == 0:
        findings.append(
            ValidationFinding(
                code=_NO_ENTRY_BLOCK_CODE,
                message=(f"Skill {skill.id!r} has no entry ordered block."),
            )
        )
        return findings
    if len(entries) > 1:
        named = ", ".join(repr(block_id) for block_id in entries)
        findings.append(
            ValidationFinding(
                code=_MULTIPLE_ENTRY_BLOCKS_CODE,
                message=(
                    f"Skill {skill.id!r} has more than one entry ordered block: "
                    f"{named}."
                ),
            )
        )
        return findings
    findings.extend(_silence_timeout_hangup_block_findings(skill, blocks))
    unreachable = unreachable_ordered_block_ids(skill)
    if unreachable:
        named = ", ".join(repr(block_id) for block_id in unreachable)
        noun = "ordered block" if len(unreachable) == 1 else "ordered blocks"
        verb = "is" if len(unreachable) == 1 else "are"
        findings.append(
            ValidationFinding(
                code=_UNREACHABLE_ORDERED_BLOCK_CODE,
                message=(
                    f"Skill {skill.id!r} {noun} {named} {verb} not reachable "
                    f"from the entry block {entries[0]!r}."
                ),
            )
        )
    return findings


def _silence_timeout_hangup_block_findings(
    skill: Skill, blocks: list[OrderedBlock]
) -> list[ValidationFinding]:
    """Reject a ``hangup`` block left on the silence check-in skill.

    Hangup is its own skill. Checked after the several-entries return so an
    untargeted ``hangup`` block still reports ``multiple_entry_blocks`` only.
    """
    from rasa.mantle.default_skills import DEFAULT_SILENCE_TIMEOUT

    if skill.id != DEFAULT_SILENCE_TIMEOUT:
        return []
    if not any(block.block_id == _SILENCE_TIMEOUT_HANGUP_BLOCK_ID for block in blocks):
        return []
    return [
        ValidationFinding(
            code=_SILENCE_TIMEOUT_HANGUP_BLOCK_CODE,
            message=(
                f"Skill {skill.id!r} must not contain the hangup block. "
                "Hangup is the skill 'default_silence_timeout_hangup'."
            ),
        )
    ]


def validate_prose_instruction_scopes(
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> list[ValidationFinding]:
    """Check prose ``if:`` conditions on loaded skills are authorable.

    Structural ``else:`` / ``elif:`` / empty-body errors are raised at
    ``skill.md`` compile time (helpers in
    :mod:`~rasa.mantle.skills.prose_scoping`) and surface via
    :func:`validate_skill_loading`. Empty ``if:`` conditions use the shared
    :func:`~rasa.mantle.skills.prose_scoping.is_empty_prose_if_condition`
    predicate. This check also covers unsupported expression constructs and
    memory that the skill cannot read at runtime (see
    :func:`~rasa.mantle.memory.manager.readable_memory_slot_names` — the same
    rules as ``MemoryManager.read_all`` / prompt filtering).
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        known_memory_keys = readable_memory_slot_names(
            catalog, project_memory, skill.id
        )
        findings.extend(_prose_scope_findings_for_skill(skill, known_memory_keys))
    return findings


def _prose_scope_findings_for_skill(
    skill: Skill,
    known_memory_keys: frozenset[str],
) -> list[ValidationFinding]:
    """Return findings for one skill's prose ``if:`` condition strings."""
    findings: list[ValidationFinding] = []
    for segment in prose_segments_from_body(skill):
        if segment.condition is None:
            continue
        if is_empty_prose_if_condition(segment.condition):
            findings.append(
                ValidationFinding(
                    code=_EMPTY_IF_CONDITION_CODE,
                    message=(
                        f"Skill {skill.id!r} has a prose 'if:' segment with an "
                        "empty condition. Provide an expression such as "
                        "'session.<skill_id>.<entry> == …'."
                    ),
                )
            )
            continue
        condition = segment.condition.strip()
        try:
            validate_condition_syntax(condition)
        except ConditionEvaluationError as exc:
            findings.append(
                ValidationFinding(
                    code=_INVALID_IF_EXPRESSION_CODE,
                    message=(
                        f"Skill {skill.id!r} has an invalid prose 'if:' "
                        f"condition {condition!r}: {exc}. Fix the expression "
                        "or move exclusive branching into an ordered block."
                    ),
                )
            )
            continue
        for memory_key in sorted(extract_memory_keys(condition)):
            if memory_key in known_memory_keys:
                continue
            findings.append(
                ValidationFinding(
                    code=_UNKNOWN_MEMORY_KEY_CODE,
                    message=(
                        f"Skill {skill.id!r} has a prose 'if:' condition "
                        f"referencing memory key {memory_key!r} that is not "
                        "readable while this skill is active. Use this "
                        "skill's own memory.yml fields, another skill's "
                        "public fields, or project memory.yml (not another "
                        "skill's private slots)."
                    ),
                )
            )
    return findings


def validate_prose_memory_references(
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> list[ValidationFinding]:
    """Check ``@memory`` tokens in LLM-facing instruction text are readable.

    Scans outer prose segment **bodies** (not ``if:`` conditions) and
    ordered-block :class:`~rasa.mantle.skills.steps.AutonomousStep`
    ``instructions``. Uses the same readable set as
    :func:`~rasa.mantle.memory.manager.readable_memory_slot_names` (own
    public+private, other skills' public, project).
    ``@memory.system.*`` is never readable and always fails.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        known_memory_keys = readable_memory_slot_names(
            catalog, project_memory, skill.id
        )
        findings.extend(
            _prose_memory_reference_findings_for_skill(skill, known_memory_keys)
        )
    return findings


def _prose_memory_reference_findings_for_skill(
    skill: Skill,
    known_memory_keys: frozenset[str],
) -> list[ValidationFinding]:
    """Return findings for unreadable ``@memory`` tokens on one skill."""
    findings: list[ValidationFinding] = []
    seen_unreadable: set[str] = set()
    for text in llm_facing_instruction_texts(skill):
        for memory_key in collect_prose_memory_references(text):
            if memory_key in known_memory_keys or memory_key in seen_unreadable:
                continue
            seen_unreadable.add(memory_key)
            findings.append(
                ValidationFinding(
                    code=_UNKNOWN_MEMORY_REFERENCE_CODE,
                    message=(
                        f"Skill {skill.id!r} references "
                        f"'@memory.{memory_key}' in instruction prose, but "
                        "that memory is not readable while this skill is "
                        "active. Use this skill's own fields (public or "
                        "private), another skill's public fields, or "
                        "project memory. "
                        "'@memory.system.*' is not supported."
                    ),
                )
            )
    return findings


def collect_incomplete_memory_reference_findings(
    catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Error when instruction bodies contain incomplete ``@memory`` lookalikes.

    Live substitution only understands ``@memory.<namespace>.<entry>``. Bare
    or one-segment forms (``@memory``, ``@memory.project``) cannot be
    substituted; fail train so authors fix the token before deploy.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        seen: set[str] = set()
        for text in llm_facing_instruction_texts(skill):
            for token in collect_incomplete_prose_memory_tokens(text):
                if token in seen:
                    continue
                seen.add(token)
                findings.append(
                    ValidationFinding(
                        code=_INCOMPLETE_MEMORY_REFERENCE_CODE,
                        message=(
                            f"Skill {skill.id!r} contains {token!r} in "
                            "instruction prose. Live values require "
                            "'@memory.<namespace>.<entry>' (for example "
                            "'@memory.project.card_id'); incomplete tokens "
                            "are left as literal text at runtime."
                        ),
                    )
                )
    return findings


def collect_incomplete_prose_at_token_findings(
    catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Error when instruction bodies contain incomplete ``@skill``/``@block``/``@tool``.

    Live substitution and catalog wiring only understand one-segment tokens
    (``@skill.<skill_id>``, ``@block.<block_id>``, ``@tool.<name>``). Bare or
    extra-segment forms are left as literal text; fail train so authors fix
    them before deploy.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        seen: set[str] = set()
        for text in llm_facing_instruction_texts(skill):
            for token in collect_incomplete_prose_at_tokens(text):
                if token in seen:
                    continue
                seen.add(token)
                findings.append(
                    ValidationFinding(
                        code=_INCOMPLETE_AT_REFERENCE_CODE,
                        message=(
                            f"Skill {skill.id!r} contains {token!r} in "
                            "instruction prose. Use '@skill.<skill_id>', "
                            "'@block.<block_id>', or '@tool.<name>' (a "
                            "single id after the prefix); incomplete tokens "
                            "are left as literal text at runtime."
                        ),
                    )
                )
    return findings


def collect_session_reference_in_instruction_findings(
    catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Error when instruction bodies contain ``session.<namespace>.<entry>``.

    ``session.*`` belongs in ``if:`` conditions. In LLM-facing instruction
    prose authors almost certainly meant ``@memory.…`` for a live value.
    Conditions are not scanned here.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        seen: set[str] = set()
        for text in llm_facing_instruction_texts(skill):
            for match in _PROSE_SESSION_REF_PATTERN.finditer(text):
                session_path = f"session.{match.group(1)}.{match.group(2)}"
                if session_path in seen:
                    continue
                seen.add(session_path)
                findings.append(
                    ValidationFinding(
                        code=_SESSION_IN_INSTRUCTIONS_CODE,
                        message=(
                            f"Skill {skill.id!r} contains {session_path!r} in "
                            "instruction prose. 'session.*' belongs in 'if:' "
                            "conditions and structured fields; it is not "
                            "substituted in free prose. For a live value in "
                            "instructions, use a readable "
                            "'@memory.<namespace>.<entry>' token, or move this "
                            "reference into an 'if:' condition."
                        ),
                    )
                )
    return findings


def validate_execute_step_parameters(
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> list[ValidationFinding]:
    """Check ``execute_tool`` parameters that look like ``session.*`` references.

    Plain literals (``full``, numbers, booleans) are left alone. Values that
    start with ``session.`` must be a canonical two-level reference
    (``session.<namespace>.<entry>``) naming memory readable while the skill
    is active — same visibility rules as prose ``if:`` conditions. Malformed
    lookalikes (one-level paths, operators, invalid syntax) fail at train time
    instead of being passed through as literal tool arguments at runtime.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        known_memory_keys = readable_memory_slot_names(
            catalog, project_memory, skill.id
        )
        findings.extend(
            _execute_step_parameter_findings_for_skill(skill, known_memory_keys)
        )
    return findings


def _looks_like_session_reference(value: str) -> bool:
    """Return whether *value* is authored as a ``session.*`` path or expression."""
    return value.strip().startswith("session.")


def _execute_step_parameter_findings_for_skill(
    skill: Skill,
    known_memory_keys: frozenset[str],
) -> list[ValidationFinding]:
    """Return findings for one skill's ``ExecuteStep.parameters`` values."""
    findings: list[ValidationFinding] = []
    for target in iter_resolved_activation_targets(skill):
        for step in target.steps:
            if not isinstance(step, ExecuteStep):
                continue
            for param_name, param_value in step.parameters.items():
                if not isinstance(param_value, str):
                    continue
                memory_key = _try_parse_session_reference(param_value)
                if memory_key is not None:
                    if memory_key not in known_memory_keys:
                        findings.append(
                            ValidationFinding(
                                code=_UNKNOWN_EXECUTE_SESSION_PARAM_CODE,
                                message=(
                                    f"Skill {skill.id!r} flow "
                                    f"{target.target_id!r} step "
                                    f"{step.id!r} parameter {param_name!r} "
                                    f"references memory key {memory_key!r} that "
                                    "is not readable while this skill is active. "
                                    "Use this skill's own memory.yml fields, "
                                    "another skill's public fields, or project "
                                    "memory.yml (not another skill's private "
                                    "slots)."
                                ),
                            )
                        )
                    continue
                if not _looks_like_session_reference(param_value):
                    continue
                findings.append(
                    ValidationFinding(
                        code=_INVALID_EXECUTE_SESSION_PARAM_CODE,
                        message=(
                            f"Skill {skill.id!r} flow {target.target_id!r} step "
                            f"{step.id!r} parameter {param_name!r} value "
                            f"{param_value!r} looks like a session reference "
                            "but is not the namespaced form "
                            "'session.<skill_id|project|system>.<entry_name>'. "
                            "Fix the reference, or use a plain literal string "
                            "that does not start with 'session.'."
                        ),
                    )
                )
    return findings


def validate_flow_transitions(catalog: SkillCatalog) -> list[ValidationFinding]:
    """Check every ``next`` target resolves to a step in the same flow or END."""
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        for target in iter_resolved_activation_targets(skill):
            findings.extend(_flow_transition_findings(skill, target))
    return findings


def _flow_transition_findings(
    skill: Skill, resolved_target: ResolvedActivationTarget
) -> list[ValidationFinding]:
    """Report invalid ``next`` routing in a resolved target."""
    valid_targets = {step.id for step in resolved_target.steps} | {END_STEP}
    findings = [
        ValidationFinding(
            code="mantle.validation.flow.unresolved_next",
            message=(
                f"Step {step.id!r} of flow {resolved_target.target_id!r} "
                f"(skill {skill.id!r}, "
                f"{_resolved_target_location(resolved_target)}) "
                f"routes to {target!r}, which is not a step in "
                "the flow. Point 'next' at an existing step id "
                "or 'END'."
            ),
        )
        for step in resolved_target.steps
        for target in _next_targets(step)
        if target not in valid_targets
    ]
    findings.extend(
        ValidationFinding(
            code="mantle.validation.flow.next_missing_else",
            message=(
                f"Step {step.id!r} of ordered block "
                f"{resolved_target.target_id!r} "
                f"(skill {skill.id!r}, "
                f"{_resolved_target_location(resolved_target)}) "
                "has conditional 'next' branches but no 'else'. "
                "Add an 'else' branch so routing always has a fallback "
                "(use 'else: END' to finish the ordered block)."
            ),
        )
        for step in resolved_target.steps
        if _next_has_if_without_else(step)
    )
    return findings


def _next_has_if_without_else(step: Step) -> bool:
    """Test whether a branched ``next`` has conditions but no fallback."""
    next_value = getattr(step, "next", None)
    if not isinstance(next_value, list):
        return False
    has_if = any(branch.if_ is not None for branch in next_value)
    has_else = any(branch.if_ is None for branch in next_value)
    return has_if and not has_else


def validate_links_and_calls(
    project_catalog: SkillCatalog, merged_catalog: SkillCatalog
) -> list[ValidationFinding]:
    """Check ``link`` / ``call`` targets resolve to a known, activatable target.

    Targets are resolved against *merged_catalog* the same way runtime activation
    does: explicit compiled ids match directly; bare skill ids map to the
    callee's entry target via
    :func:`~rasa.mantle.skills.catalog.resolve_call_activation_target_id`
    and :func:`~rasa.mantle.skills.catalog.resolve_link_activation_target_id`.

    Internal ordered blocks (``routable`` ``False``) must not be ``call`` /
    ``link`` targets from any skill. They are entered only via same-skill LLM
    ``activate`` while the inline family is active. An ordered block must not
    ``call:`` or ``link:`` the id of the skill that contains it. That target
    means "start this skill", and starting the skill starts its entry block.
    When that entry is the block that contains the step, the block starts
    itself again.
    """
    findings: list[ValidationFinding] = []
    for skill in project_catalog.skills.values():
        for target in iter_resolved_activation_targets(skill):
            for step in target.steps:
                findings.extend(
                    _findings_for_link_or_call_step(skill, target, step, merged_catalog)
                )
    return findings


def _findings_for_link_or_call_step(
    skill: Skill,
    resolved_target: ResolvedActivationTarget,
    step: Step,
    merged_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Validate one step's ``link`` / ``call`` target, if any."""
    target, keyword = _link_or_call_target(step)
    if target is None:
        return []
    if target == skill.id:
        return [
            ValidationFinding(
                code="mantle.validation.skill.self_skill_not_callable",
                message=(
                    f"Step {step.id!r} in skill {skill.id!r} "
                    f"({_resolved_target_location(resolved_target)}) uses "
                    f"'{keyword}: {target}'. An ordered block cannot call or "
                    "link the skill that contains it. That starts the skill "
                    "again, which starts its entry block."
                ),
            )
        ]
    if not _link_or_call_target_resolves(merged_catalog, target, keyword):
        return [
            ValidationFinding(
                code=f"mantle.validation.flow.unresolved_{keyword}",
                message=(
                    f"Step {step.id!r} of flow {resolved_target.target_id!r} (skill "
                    f"{skill.id!r}, {_resolved_target_location(resolved_target)}) uses "
                    f"'{keyword}: {target}', but no activation target "
                    "with that id exists in the project or the bundled "
                    "default skills."
                ),
            )
        ]
    resolved_call_target = _resolved_link_or_call_target(
        merged_catalog, target, keyword
    )
    # Non-routable same-skill ordered blocks are not call/link targets.
    if resolved_call_target is not None and not resolved_call_target.routable:
        return [
            ValidationFinding(
                code="mantle.validation.flow.internal_not_callable",
                message=(
                    f"Step {step.id!r} in skill {skill.id!r} "
                    f"({_resolved_target_location(resolved_target)}) uses "
                    f"'{keyword}: {target}', but {target!r} is another "
                    "ordered block in the same skill. Use call/link only "
                    "to start a different skill. Switching between "
                    "ordered blocks in this skill happens while the "
                    "skill is already active — do not point call/link "
                    "at them."
                ),
            )
        ]
    return []


def _resolved_link_or_call_target(
    catalog: SkillCatalog, target: str, keyword: str
) -> ResolvedActivationTarget | None:
    """Return the target that runtime activation would push for *target*."""
    if keyword == "call":
        flow_id = resolve_call_activation_target_id(catalog, target)
    else:
        flow_id = resolve_link_activation_target_id(catalog, target)
    return catalog.resolve_activation_target(flow_id)


def _link_or_call_target_resolves(
    catalog: SkillCatalog, target: str, keyword: str
) -> bool:
    """Return whether *target* resolves the same way as runtime activation."""
    if catalog.resolve_activation_target(target) is not None:
        return True
    if catalog.owning_skill_for_target_id(target) is None:
        return False
    if keyword == "call":
        flow_id = resolve_call_activation_target_id(catalog, target)
    else:
        flow_id = resolve_link_activation_target_id(catalog, target)
    return catalog.resolve_activation_target(flow_id) is not None


def validate_responses_and_actions(
    catalog: SkillCatalog, response_names: set[str]
) -> list[ValidationFinding]:
    """Check action/utterance references against the merged response registry.

    The engine has no custom action server, so a flow ``action`` must be either
    an ``utter_*`` response that exists, or a built-in action the step executor
    can dispatch (:data:`~rasa.mantle.skills.steps.SUPPORTED_BUILTIN_ACTIONS`).
    Explicit collect ``utterance`` names that look like responses must also
    exist.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        for target in iter_resolved_activation_targets(skill):
            for step in target.steps:
                findings.extend(_action_findings(skill, target, step, response_names))
    return findings


def validate_tool_and_verbatim_refs(
    catalog: SkillCatalog, responses: ResponseRegistry
) -> list[ValidationFinding]:
    """Validate tool-gate and ``utter:`` response refs in one catalog pass.

    Checks:

    - ``on_success`` / ``on_failure``, skill ``utter:``, and
      ``requires_confirmation`` ask/denial names exist in *responses* and every
      variant row has non-whitespace ``text`` (empty bodies are skipped at
      runtime with a log only). Omitted confirmation names leave that response
      to the LLM.

    Skill- and flow-level gates that share the same name and field values are
    checked once so markdown merge (flow tools folded into skill logic) does
    not double-report.
    """
    findings: list[ValidationFinding] = []
    for skill in catalog.skills.values():
        for gate, location in _iter_tool_gates(skill):
            findings.extend(
                _gated_tool_ref_findings(
                    skill=skill, gate=gate, location=location, responses=responses
                )
            )
        for trigger in skill.verbatim_triggers:
            findings.extend(
                _response_ref_findings(
                    response_name=trigger.response_name,
                    responses=responses,
                    unknown_code=_UNKNOWN_VERBATIM_TRIGGER_RESPONSE_CODE,
                    unknown_message=(
                        f"Skill {skill.id!r} utter trigger "
                        f"{trigger.response_name!r} is not defined in any "
                        "responses.yml."
                    ),
                    empty_message=(
                        f"Skill {skill.id!r} utter trigger "
                        f"{trigger.response_name!r} references a response with "
                        "an empty body in responses.yml; provide non-whitespace "
                        "text."
                    ),
                )
            )
    return findings


def validate_cancel_skill_confirmation_refs(
    confirmation: RequiresConfirmation | None,
    responses: ResponseRegistry,
) -> list[ValidationFinding]:
    """Check ``cancel`` confirmation response names against the registry.

    Omitted names leave the wording to the model. A set name must exist and
    every variant must have non-whitespace text. Finding codes match a skill
    tool's ``requires_confirmation``.
    """
    if confirmation is None:
        return []
    findings: list[ValidationFinding] = []
    location = f"orchestrator.tool_constraints.{TOOL_CANCEL}"
    for field_name, response_name in (
        (UTTER_FOR_CONFIRMATION_FIELD, confirmation.utter_for_confirmation),
        (UTTER_ON_USER_DENIAL_FIELD, confirmation.utter_on_user_denial),
    ):
        if response_name is None:
            continue
        field_path = f"{REQUIRES_CONFIRMATION_FIELD}.{field_name}"
        findings.extend(
            _response_ref_findings(
                response_name=response_name,
                responses=responses,
                unknown_code=_UNKNOWN_REQUIRES_CONFIRMATION_RESPONSE_CODE,
                unknown_message=(
                    f"{location} sets {field_path}={response_name!r}, but no "
                    "such response is defined in any responses.yml."
                ),
                empty_message=(
                    f"{location} sets {field_path}={response_name!r}, but that "
                    "response has an empty body in responses.yml; provide "
                    "non-whitespace text."
                ),
            )
        )
    return findings


def validate_default_skills(
    default_result: SkillCatalogLoadResult,
) -> list[ValidationFinding]:
    """Check every bundled default skill actually loaded.

    The default-skill loader logs-and-skips unparseable skills, so a broken
    bundled skill would otherwise silently disappear from the catalog (and the
    project would run without it). Load errors are always reported — even when
    every bundled skill failed to parse — while an empty catalog *without* load
    errors indicates a broken installation missing its packaged skills.
    """
    findings = [
        ValidationFinding(
            code="mantle.validation.default_skills.failed_to_load",
            message=(
                f"Bundled default skill directory {directory!r} failed to load "
                f"and would be silently skipped: {error}. The rasa installation "
                "is broken; reinstall it or report the problem."
            ),
        )
        for directory, error in default_result.load_errors
    ]
    if not default_result.catalog.skills and not findings:
        findings.append(
            ValidationFinding(
                code="mantle.validation.default_skills.none_bundled",
                message=(
                    "No bundled default skills were loaded. The rasa "
                    "installation is missing its packaged default skills."
                ),
            )
        )
    return findings


def collect_bundled_default_skill_authoring_findings(
    default_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Run skill authoring checks that apply to bundled default skills.

    :func:`validate_default_skills` only reports load failures. Defaults are
    otherwise skipped by project-catalog checks, so a shipped default with a
    missing description or incomplete ``@`` token would train cleanly. These
    checks keep packaged skills under the same authoring rules as project
    skills.
    """
    findings: list[ValidationFinding] = []
    findings.extend(validate_skill_descriptions(default_catalog))
    findings.extend(validate_ordered_block_structure(default_catalog))
    findings.extend(collect_incomplete_memory_reference_findings(default_catalog))
    findings.extend(collect_incomplete_prose_at_token_findings(default_catalog))
    findings.extend(collect_session_reference_in_instruction_findings(default_catalog))
    return findings


def validate_unsupported_request_handler_override(
    project_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Check a project override of the unsupported-request handler stays conformant.

    The engine reaches ``default_unsupported_request_handler`` only via the
    ``cannot_help`` tool: dispatch seeds ``request_type`` and activates the skill's
    catalog entry. Three things must hold or ``cannot_help`` misbehaves, so they are
    enforced at train time rather than failing silently mid-conversation:

    * ``engine_managed`` stays ``true`` — else the handler is LLM-routable and can
      be activated directly, bypassing the seed and its audit event.
    * ``request_type`` is declared — the dispatch seeds it and the gate branches
      on it.
    * the skill has a catalog entry.

    How the override phrases the decline itself is left to the builder. The
    bundled skill is trusted; only a project override is checked.
    """
    from rasa.mantle.default_skills import (
        DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
        REQUEST_TYPE_ENTRY,
    )

    skill = project_catalog.skills.get(DEFAULT_UNSUPPORTED_REQUEST_HANDLER)
    if skill is None:
        return []

    findings: list[ValidationFinding] = []
    prefix = f"Project override of {DEFAULT_UNSUPPORTED_REQUEST_HANDLER!r}: "

    # engine_managed must stay true — otherwise the handler becomes LLM-routable
    # and can be activated directly, bypassing the cannot_help seed + audit event.
    if not skill.engine_managed:
        findings.append(
            ValidationFinding(
                code="mantle.validation.unsupported_request_handler.not_engine_managed",
                message=(
                    f"{prefix}routing.engine_managed must stay true. Otherwise the "
                    "decline skill becomes LLM-routable and can be activated "
                    "directly, bypassing the cannot_help seed and its audit event."
                ),
            )
        )

    # request_type must be declared — the dispatch seeds it and the decline gate
    # branches on it; an override that drops it makes declines unreliable.
    if REQUEST_TYPE_ENTRY not in skill.memory.definition.all_fields():
        findings.append(
            ValidationFinding(
                code="mantle.validation.unsupported_request_handler.missing_request_type",
                message=(
                    f"{prefix}the {REQUEST_TYPE_ENTRY!r} memory entry must be "
                    "declared. The cannot_help dispatch seeds it and the decline "
                    "gate branches on it; without it the decline cannot be seeded."
                ),
            )
        )

    # The override must have a catalog entry. cannot_help activates that entry
    # (prose id or ordered-block id); an override with no flows would pass train
    # yet fail every decline at runtime ("decline skill not available").
    if entry_target_id_for_skill(skill) is None:
        findings.append(
            ValidationFinding(
                code="mantle.validation.unsupported_request_handler.missing_entry",
                message=(
                    f"{prefix}it must define an entry flow. cannot_help activates "
                    "the catalog entry for the override."
                ),
            )
        )

    # Note: we deliberately do NOT require a specific decline shape (e.g. an
    # ``utter_*`` step). A builder overriding the skill may legitimately decline
    # via a different mechanism, and "has an utter step" would neither prove the
    # skill always utters nor allow valid alternatives. The checks above are the
    # load-bearing contract; how the override phrases the decline is its own.
    return findings


def validate_skill_identifiers(
    project_catalog: SkillCatalog,
    *,
    bundled_default_ids: frozenset[str],
) -> list[ValidationFinding]:
    """Check project skill ids and the ``routing.is_default`` restriction.

    Args:
        project_catalog: Project skills only (defaults merged separately at runtime).
        bundled_default_ids: Skill ids from the already-loaded bundled default
            catalog. Callers must pass ids from
            :func:`~rasa.mantle.skills.catalog.load_default_skill_catalog_result`
            so validation does not re-invoke the strict runtime loader.
    """
    findings: list[ValidationFinding] = []
    for skill in project_catalog.skills.values():
        if skill.id in _RESERVED_SKILL_IDS:
            findings.append(
                ValidationFinding(
                    code="mantle.validation.skill.reserved_id",
                    message=(
                        f"A skill may not be named {skill.id!r}; "
                        f"{PROJECT_NAMESPACE!r} and {SYSTEM_NAMESPACE!r} are "
                        "reserved memory namespaces. Rename the skill "
                        "directory or its 'id'."
                    ),
                )
            )
        if "." in skill.id:
            findings.append(
                ValidationFinding(
                    code="mantle.validation.skill.invalid_id",
                    message=(
                        f"Skill id {skill.id!r} must not contain a '.'; it is "
                        "used as a memory namespace prefix. Rename it."
                    ),
                )
            )
        if skill.is_default and skill.id not in bundled_default_ids:
            findings.append(
                ValidationFinding(
                    code="mantle.validation.skill.is_default_not_allowed",
                    message=(
                        f"Project skill {skill.id!r} sets 'routing.is_default: "
                        "true', which is reserved for bundled default skills. "
                        "Remove it."
                    ),
                )
            )
    return findings


def call_target_exists(skill_catalog: SkillCatalog, target: str) -> bool:
    """Return whether *target* resolves the same way as runtime activation."""
    if skill_catalog.resolve_activation_target(target) is not None:
        return True
    skill = skill_catalog.owning_skill_for_target_id(target)
    if skill is None or target != skill.id:
        return False
    if not skill.body:
        return True
    entry_target_id = resolve_call_activation_target_id(skill_catalog, target)
    return skill_catalog.resolve_activation_target(entry_target_id) is not None


def collect_referenced_skill_findings(
    skill_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Return one finding per unresolved ``referenced_skills`` entry."""
    findings: list[ValidationFinding] = []
    for skill in skill_catalog.skills.values():
        for target in skill.referenced_skills:
            if call_target_exists(skill_catalog, target):
                continue
            findings.append(
                ValidationFinding(
                    code=_REFERENCED_TARGET_CODE,
                    message=(
                        f"Skill {skill.id!r} references external call/link target "
                        f"{target!r}, which does not resolve to a skill or flow "
                        "in the catalog."
                    ),
                )
            )
    return findings


def collect_bare_skill_mention_findings(
    skill_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Warn when prose names a known skill id without the ``@skill.`` prefix.

    A bare mention does not compile into ``referenced_skills``, so activating
    that skill at runtime becomes a topic-change digression (interrupt +
    resume prompt) instead of a delegated call — almost never what the
    author meant when naming the skill in prose. Warning severity: the
    project still trains, the author just gets pointed at the fix.
    """
    findings: list[ValidationFinding] = []
    for skill in skill_catalog.skills.values():
        if skill.engine_managed or skill.is_default:
            continue
        other_ids = [
            candidate_id
            for candidate_id, candidate in skill_catalog.skills.items()
            if candidate_id != skill.id
            and not (candidate.engine_managed or candidate.is_default)
        ]
        if not other_ids:
            continue
        # Standalone-word matches only; the dotted-path lookbehind also
        # excludes correctly written ``@skill.<id>`` tokens.
        pattern = re.compile(
            r"(?<!\w)(?<!\w\.)("
            + "|".join(re.escape(other_id) for other_id in other_ids)
            + r")(?!\w)(?!\.\w)"
        )
        seen: set[str] = set()
        prose_texts = [segment.text for segment in prose_segments_from_body(skill)]
        for text in prose_texts:
            for match in pattern.finditer(text):
                mentioned_id = match.group(1)
                if mentioned_id in seen:
                    continue
                seen.add(mentioned_id)
                findings.append(
                    ValidationFinding(
                        code=_BARE_SKILL_MENTION_CODE,
                        severity="warning",
                        message=(
                            f"Skill {skill.id!r} mentions skill "
                            f"{mentioned_id!r} in prose without the "
                            f"'@skill.' prefix. The mention does not compile "
                            f"into referenced_skills, so activating it at "
                            f"runtime interrupts {skill.id!r} instead of "
                            f"delegating to it. Write "
                            f"'@skill.{mentioned_id}' to reference it."
                        ),
                    )
                )
    return findings


def collect_hidden_prose_skill_reference_findings(
    skill_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Return one finding per prose ``@skill`` token targeting a hidden skill.

    Deterministic ``call:`` / ``link:`` steps and ``resolve_with`` bindings
    are not collected here; those paths may still start a hidden skill.
    """
    findings: list[ValidationFinding] = []
    for skill in skill_catalog.skills.values():
        prose_text = "\n".join(
            segment.text for segment in prose_segments_from_body(skill)
        )
        seen: set[str] = set()
        for target_id in collect_prose_skill_references(prose_text):
            if target_id in seen:
                continue
            seen.add(target_id)
            target = skill_catalog.skill_by_id(target_id)
            if target is None or not target.hidden:
                continue
            findings.append(
                ValidationFinding(
                    code=_HIDDEN_PROSE_SKILL_REF_CODE,
                    message=(
                        f"Skill {skill.id!r} references hidden skill "
                        f"{target_id!r} via '@skill.{target_id}' in prose. "
                        "Hidden skills cannot be started from routing; use a "
                        "deterministic call: or link: step, or bind the skill "
                        "as resolve_with in agent.yml orchestrator.preconditions."
                    ),
                )
            )
    return findings


def collect_referenced_block_findings(
    skill_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Return one finding per unresolved ``referenced_blocks`` entry."""
    findings: list[ValidationFinding] = []
    for skill in skill_catalog.skills.values():
        local_target_ids = {
            target.target_id for target in iter_resolved_activation_targets(skill)
        }
        for target in skill.referenced_blocks:
            if target in local_target_ids:
                continue
            findings.append(
                ValidationFinding(
                    code=_REFERENCED_BLOCK_CODE,
                    message=(
                        f"Skill {skill.id!r} references ordered block flow "
                        f"{target!r}, which is not a flow on this skill."
                    ),
                )
            )
    return findings


def validate_referenced_skills(skill_catalog: SkillCatalog) -> None:
    """Check every compiled ``referenced_skills`` entry resolves in the catalog.

    Args:
        skill_catalog: The loaded skill catalog (project + default skills).

    Raises:
        ValidationError: When one or more parent skills reference a missing target.
    """
    findings = collect_referenced_skill_findings(skill_catalog)
    if not findings:
        return
    raise ValidationError(
        code=_REFERENCED_TARGET_CODE,
        event_info=(
            "These call:/link: targets do not resolve to a skill or flow in the "
            "catalog:\n  " + "\n  ".join(finding.message for finding in findings)
        ),
    )


def _project_shared_tool_names(project_root: Path) -> set[str]:
    """Return ``@tool`` names defined under *project_root*/``tools/``."""
    return set(load_shared_tools(project_root).keys())


def _project_skill_local_tool_owners(project_root: Path) -> dict[str, str]:
    """Map skill-local tool name → owning skill id under *project_root*."""
    skills_root = project_root / MANTLE_SKILLS_DIR
    if not skills_root.is_dir():
        return {}

    owners: dict[str, str] = {}
    for skill_dir in sorted(skills_root.iterdir()):
        if not skill_dir.is_dir():
            continue
        skill_id = skill_dir.name
        for name in load_tools_for_flow(skill_id, skills_root):
            owners[name] = skill_id
    return owners


def _python_tool_names_for_skill(
    skill: Skill,
    skill_catalog: SkillCatalog,
    project_root: Path,
    shared_names: set[str],
) -> set[str]:
    """Return Python ``@tool`` names this skill would bind at model load.

    Matches :func:`rasa.mantle.tools.mcp_import_spec.parse_mcp_imports`: skill-local
    tools, shared tools declared on this skill's gates, and shared names listed
    in this skill's ``import_tools``. Tools that belong only to other skills, or
    unused shared modules, are excluded.
    """
    skills_root = project_root / MANTLE_SKILLS_DIR
    local_names: set[str] = set()
    if skills_root.is_dir():
        local_names = set(load_tools_for_flow(skill.id, skills_root))
    declared = skill_catalog.declared_tool_names(skill.id)
    imported_shared = {
        name
        for name in skill.import_tool_names
        if not name.startswith("mcp/") and name in shared_names
    }
    return local_names | (shared_names & declared) | imported_shared


def collect_import_tools_findings(
    skill_catalog: SkillCatalog,
    project_root: Path,
) -> list[ValidationFinding]:
    """Return one finding per invalid ``import_tools`` entry."""
    from rasa.mantle.config.mcp import load_integration_mcp_servers
    from rasa.mantle.llm.tool_schemas import FRAMEWORK_TOOL_NAMES
    from rasa.mantle.tools.mcp_import_spec import try_parse_mcp_tool_import

    shared_names = _project_shared_tool_names(project_root)
    local_owners = _project_skill_local_tool_owners(project_root)
    try:
        mcp_settings = load_integration_mcp_servers(project_root)
        mcp_server_ids = (
            set(mcp_settings.servers) if mcp_settings is not None else set()
        )
    except Exception:
        # The integrations validator reports malformed config separately.
        mcp_server_ids = set()
    findings: list[ValidationFinding] = []

    for skill in skill_catalog.skills.values():
        imported_bare_names: set[str] = set()
        for name in sorted(skill.import_tool_names):
            try:
                mcp_import = try_parse_mcp_tool_import(name)
            except ValueError as exc:
                findings.append(
                    ValidationFinding(code=_IMPORT_TOOLS_CODE, message=str(exc))
                )
                continue

            if mcp_import is not None:
                if mcp_import.server_id not in mcp_server_ids:
                    findings.append(
                        ValidationFinding(
                            code=_IMPORT_TOOLS_CODE,
                            message=(
                                f"Skill {skill.id!r} imports MCP tool {name!r}, but "
                                f"server {mcp_import.server_id!r} is not configured "
                                "under mcp_servers in integrations.yml."
                            ),
                        )
                    )
                if mcp_import.tool_name in imported_bare_names:
                    findings.append(
                        ValidationFinding(
                            code=_IMPORT_TOOLS_CODE,
                            message=(
                                f"Skill {skill.id!r} imports multiple MCP tools "
                                f"with bare name {mcp_import.tool_name!r}."
                            ),
                        )
                    )
                imported_bare_names.add(mcp_import.tool_name)
                colliding_python = _python_tool_names_for_skill(
                    skill, skill_catalog, project_root, shared_names
                )
                if mcp_import.tool_name in FRAMEWORK_TOOL_NAMES:
                    findings.append(
                        ValidationFinding(
                            code=_IMPORT_TOOLS_CODE,
                            message=(
                                f"Skill {skill.id!r} MCP import {name!r} reuses "
                                f"reserved framework tool name "
                                f"{mcp_import.tool_name!r}."
                            ),
                        )
                    )
                elif mcp_import.tool_name in colliding_python:
                    findings.append(
                        ValidationFinding(
                            code=_IMPORT_TOOLS_CODE,
                            message=(
                                f"Skill {skill.id!r} MCP import {name!r} collides "
                                f"with local/shared tool {mcp_import.tool_name!r}."
                            ),
                        )
                    )
                continue

            if name in shared_names:
                continue
            if name in local_owners:
                owner = local_owners[name]
                findings.append(
                    ValidationFinding(
                        code=_IMPORT_TOOLS_CODE,
                        message=(
                            f"Skill {skill.id!r} lists import_tools entry {name!r}, "
                            f"but it is skill-local in skills/{owner}/tools/ — "
                            "remove it from import_tools."
                        ),
                    )
                )
            else:
                findings.append(
                    ValidationFinding(
                        code=_IMPORT_TOOLS_CODE,
                        message=(
                            f"Skill {skill.id!r} lists import_tools entry {name!r}, "
                            "but no shared tool exists in tools/."
                        ),
                    )
                )
    return findings


def validate_import_tools(skill_catalog: SkillCatalog, project_root: Path) -> None:
    """Check every import resolves to a shared local tool or configured MCP server.

    ``import_tools`` accepts shared ``tools/*.py`` names and explicit
    ``mcp/<server>:<tool>`` references. Skill-local tools under
    ``skills/<id>/tools/`` are auto-discovered and must not appear here.

    Args:
        skill_catalog: The loaded skill catalog (project + default skills).
        project_root: Mantle project directory (parent of ``skills/``).

    Raises:
        ValidationError: When one or more skills list invalid import_tools entries.
    """
    findings = collect_import_tools_findings(skill_catalog, project_root)
    if not findings:
        return
    raise ValidationError(
        code=_IMPORT_TOOLS_CODE,
        event_info="Invalid import_tools entries:\n  "
        + "\n  ".join(finding.message for finding in findings),
    )


def _action_findings(
    skill: Skill,
    target: ResolvedActivationTarget,
    step: Step,
    response_names: set[str],
) -> Iterable[ValidationFinding]:
    """Yield response/action findings for a single step."""
    location = f"skill {skill.id!r}, {_resolved_target_location(target)}"
    if isinstance(step, ActionStep):
        action = step.action
        if action.startswith(UTTER_PREFIX):
            if action not in response_names:
                yield ValidationFinding(
                    code="mantle.validation.response.missing",
                    message=(
                        f"Step {step.id!r} of flow {target.target_id!r} "
                        f"({location}) "
                        f"utters {action!r}, but no such response is defined in "
                        "any responses.yml."
                    ),
                )
        elif action not in SUPPORTED_BUILTIN_ACTIONS:
            yield ValidationFinding(
                code="mantle.validation.action.unknown",
                message=(
                    f"Step {step.id!r} of flow {target.target_id!r} ({location}) "
                    f"references action {action!r}, which is not executable: "
                    "only utterances ('utter_*'), 'action_listen', and "
                    "'hangup' are supported. Use an 'utter_*' response "
                    "or a tool instead."
                ),
            )
    elif isinstance(step, CollectStep) and step.utterance:
        utterance = step.utterance
        if utterance.startswith(UTTER_PREFIX) and utterance not in response_names:
            yield ValidationFinding(
                code="mantle.validation.response.missing",
                message=(
                    f"Step {step.id!r} of flow {target.target_id!r} ({location}) "
                    f"asks with {utterance!r}, but no such response is defined "
                    "in any responses.yml."
                ),
            )


def _iter_tool_gates(
    skill: Skill,
) -> Iterable[tuple[GatedTool, str]]:
    """Yield unique ``(gate, location)`` pairs for skill- and flow-level tools.

    Markdown compilation folds ordered-block tools into ``skill.tools``
    while leaving them on the flow. Exact duplicates (same name and M4 fields)
    are skipped so validation does not double-report. Differing configs for the
    same tool name are still checked separately.
    """
    seen: set[tuple[str, str | None, str | None, str | None, str | None]] = set()

    def _key(
        gate: GatedTool,
    ) -> tuple[str, str | None, str | None, str | None, str | None]:
        confirmation = gate.requires_confirmation
        ask = confirmation.utter_for_confirmation if confirmation is not None else None
        denial = confirmation.utter_on_user_denial if confirmation is not None else None
        return (gate.name, gate.on_success, gate.on_failure, ask, denial)

    for gate in skill.tools:
        seen.add(_key(gate))
        yield gate, f"skill {skill.id!r} tool_constraints"
    for target in iter_resolved_activation_targets(skill):
        location = f"skill {skill.id!r}, {_resolved_target_location(target)} tools"
        for gate in target.tools:
            key = _key(gate)
            if key in seen:
                continue
            seen.add(key)
            yield gate, location


def _gated_tool_ref_findings(
    *,
    skill: Skill,
    gate: GatedTool,
    location: str,
    responses: ResponseRegistry,
) -> list[ValidationFinding]:
    """Return findings for one tool gate's outcome and confirmation response refs."""
    findings: list[ValidationFinding] = []
    confirmation = gate.requires_confirmation
    confirmation_refs: list[tuple[str, str | None]] = []
    if confirmation is not None:
        confirmation_refs = [
            (UTTER_FOR_CONFIRMATION_FIELD, confirmation.utter_for_confirmation),
            (UTTER_ON_USER_DENIAL_FIELD, confirmation.utter_on_user_denial),
        ]
    for field_name, response_name in (
        *confirmation_refs,
        (ON_SUCCESS_FIELD, gate.on_success),
        (ON_FAILURE_FIELD, gate.on_failure),
    ):
        if response_name is None:
            continue
        if field_name in REQUIRES_CONFIRMATION_FIELDS:
            unknown_code = _UNKNOWN_REQUIRES_CONFIRMATION_RESPONSE_CODE
            field_path = f"{REQUIRES_CONFIRMATION_FIELD}.{field_name}"
        else:
            unknown_code = _UNKNOWN_ON_SUCCESS_OR_FAILURE_CODE
            field_path = field_name
        findings.extend(
            _response_ref_findings(
                response_name=response_name,
                responses=responses,
                unknown_code=unknown_code,
                unknown_message=(
                    f"Skill {skill.id!r} tool constraint {gate.name!r} "
                    f"({location}) sets {field_path}={response_name!r}, but no "
                    "such response is defined in any responses.yml."
                ),
                empty_message=(
                    f"Skill {skill.id!r} tool constraint {gate.name!r} "
                    f"({location}) sets {field_path}={response_name!r}, but that "
                    "response has an empty body in responses.yml; provide "
                    "non-whitespace text."
                ),
            )
        )
    return findings


def _response_ref_findings(
    *,
    response_name: str,
    responses: ResponseRegistry,
    unknown_code: str,
    unknown_message: str,
    empty_message: str,
) -> list[ValidationFinding]:
    """Return unknown-name or empty-body findings for one response reference."""
    if response_name not in responses.responses:
        return [
            ValidationFinding(code=unknown_code, message=unknown_message),
        ]
    registered = responses.responses[response_name]
    findings: list[ValidationFinding] = []
    for index, variant in enumerate(registered.variants):
        if variant.text.strip():
            continue
        suffix = f" (variant {index})" if len(registered.variants) > 1 else ""
        findings.append(
            ValidationFinding(
                code=_EMPTY_RESPONSE_BODY_CODE,
                message=f"{empty_message}{suffix}",
            )
        )
    return findings


def _next_targets(step: Step) -> list[str]:
    """Return the step-id targets of a step's ``next`` (plain or branched)."""
    next_value = getattr(step, "next", None)
    if next_value is None:
        return []
    if isinstance(next_value, str):
        return [next_value]
    # A list of NextBranch objects (conditional routing).
    return [branch.then for branch in next_value]


def _link_or_call_target(step: Step) -> tuple[str | None, str]:
    """Return ``(target, keyword)`` for a link/call step, else ``(None, "")``."""
    if isinstance(step, LinkStep):
        return step.link, "link"
    if isinstance(step, CallStep):
        return step.call, "call"
    return None, ""


def _resolved_target_location(target: ResolvedActivationTarget) -> str:
    """Return a human-readable source location for a resolved target."""
    return target.file_path or f"flow {target.target_id!r}"


def validate_precondition_bindings(
    project_catalog: SkillCatalog,
    merged_catalog: SkillCatalog,
    agent_spec: AgentSpec,
) -> list[ValidationFinding]:
    """Validate ``precondition`` skills against ``agent.yml`` bindings."""
    findings: list[ValidationFinding] = []
    bindings = agent_spec.preconditions
    for skill in project_catalog.skills.values():
        if skill.precondition is None:
            continue
        findings.extend(
            _findings_for_precondition_skill(
                skill, skill.precondition, bindings, merged_catalog
            )
        )
    return findings


def _findings_for_precondition_skill(
    skill: Skill,
    precondition: str,
    bindings: Mapping[str, PreconditionBinding],
    merged_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Return binding, resolver, and cycle findings for one preconditioned skill."""
    findings: list[ValidationFinding] = []
    binding = bindings.get(precondition)
    if binding is None:
        return [
            ValidationFinding(
                code=_MISSING_PRECONDITION_BINDING_CODE,
                message=(
                    f"Skill {skill.id!r} declares precondition "
                    f"{precondition!r}, but agent.yml has no "
                    "matching entry under 'orchestrator.preconditions'."
                ),
            )
        ]

    try:
        validate_condition_syntax(binding.satisfied_when)
    except ConditionEvaluationError as exc:
        findings.append(
            ValidationFinding(
                code=_INVALID_PRECONDITION_SYNTAX_CODE,
                message=(
                    f"Precondition {precondition!r} for skill "
                    f"{skill.id!r} has invalid satisfied_when "
                    f"{binding.satisfied_when!r}: {exc}"
                ),
            )
        )

    if binding.resolve_with == skill.id:
        findings.append(
            ValidationFinding(
                code=_SELF_RESOLVE_PRECONDITION_CODE,
                message=(
                    f"Skill {skill.id!r} cannot use itself as "
                    f"resolve_with for precondition {precondition!r}."
                ),
            )
        )
        return findings

    resolver = merged_catalog.skill_by_id(binding.resolve_with)
    if resolver is None:
        findings.append(
            ValidationFinding(
                code=_UNKNOWN_PRECONDITION_RESOLVER_CODE,
                message=(
                    f"Precondition {precondition!r} for skill "
                    f"{skill.id!r} references unknown resolver skill "
                    f"{binding.resolve_with!r}."
                ),
            )
        )
        return findings

    if resolver.precondition is not None:
        findings.append(
            ValidationFinding(
                code=_NESTED_PRECONDITION_RESOLVER_CODE,
                message=(
                    f"Resolver skill {binding.resolve_with!r} for "
                    f"precondition {precondition!r} must not declare "
                    f"its own precondition ({resolver.precondition!r}). "
                    "Remove preconditions from the resolver skill."
                ),
            )
        )

    visited = {skill.id}
    current_id = binding.resolve_with
    while True:
        if current_id in visited:
            findings.append(
                ValidationFinding(
                    code=_PRECONDITION_CYCLE_CODE,
                    message=(
                        f"Precondition bindings form a cycle involving "
                        f"skill {skill.id!r} and resolver "
                        f"{binding.resolve_with!r}."
                    ),
                )
            )
            break
        visited.add(current_id)
        next_skill = merged_catalog.skill_by_id(current_id)
        if next_skill is None or next_skill.precondition is None:
            break
        next_binding = bindings.get(next_skill.precondition)
        if next_binding is None:
            break
        current_id = next_binding.resolve_with

    return findings
